import random
from jobqueue import Job, ScheduleError, plan_jobs

# Show diagnostics
cases = [
    [Job("a", depends_on=("a",))],
    [Job("a", depends_on=("c",)), Job("b", depends_on=("a",)), Job("c", depends_on=("b",))],
    [Job("ok"), Job("x", depends_on=("y",)), Job("y", depends_on=("x",)), Job("z", depends_on=("x",))],
]
for c in cases:
    try:
        plan_jobs(c)
    except ScheduleError as e:
        print("ERR:", e)

# Randomized property test against a brute-force reference.
def reference(jobs):
    ids = [j.id for j in jobs]
    pos = {j.id: i for i, j in enumerate(jobs)}
    prio = {j.id: j.priority for j in jobs}
    deps = {j.id: set(j.depends_on) for j in jobs}
    remaining = set(ids)
    out = []
    while remaining:
        ready = [i for i in remaining if deps[i] <= set(out)]
        assert ready, "cycle"
        best = max(ready, key=lambda i: (prio[i], -pos[i]))
        out.append(best); remaining.remove(best)
    return out

random.seed(0)
for trial in range(500):
    n = random.randint(0, 8)
    jobs = []
    for i in range(n):
        deps = tuple(sorted(random.sample([j for j in range(i)], random.randint(0, min(i, 3)))))
        jobs.append(Job(f"j{i}", random.randint(-3, 3), tuple(f"j{d}" for d in deps)))
    shuffled = jobs[:]
    random.shuffle(shuffled)
    try:
        got = plan_jobs(shuffled)
    except ScheduleError:
        # shuffled order can introduce nothing new; DAGs built by index are acyclic
        raise AssertionError("unexpected cycle")
    expected = reference(shuffled)
    assert got == expected, (shuffled, got, expected)

    # verify dependency constraint
    idx = {j: k for k, j in enumerate(got)}
    for j in shuffled:
        for d in j.depends_on:
            assert idx[d] < idx[j.id]
print("randomized property checks passed")
